
// validate_ground_truth_comparison.js
// Paste into code.earthengine.google.com (project: rgee-auth-tillam). Compares raw Barenblitt, raw Maus,
// raw Tang & Werner, SmallMinesDS real outlines, build_02_embedding_classifier.R's OWN
// c4 mine-probability output for 2022, AND build_03_embedding_panel.R's post-processed binary
// mask for 2022 against a live Sentinel-2 2022 composite -- generated by
// validate_ground_truth_comparison.R, which uploaded the four small AOI-scoped assets this
// script reads.
//
// 2026-09-03: repointed from the old single-image binary asset (mine_prob_ghana_2022) to the
// current TILED c4 export (mine_prob_ghana_c4_2022_t{NN}, build_02 Section 10) -- there is no
// single per-year c4 image, so mosaic the year's tiles. Cutoff 45 (settled 2026-08-18), was 55.
// 2026-09-07: the repoint above never actually ran -- ee.ImageCollection(ASSET_HOME) fails because
// ghana_mining is a plain folder (IndexedFolder), not an ImageCollection. Fixed to enumerate the
// folder via ee.data.listAssets() and mosaic the matching tiles. Also added build_03's single-image
// mask_ghana_c4_2022 (post GHSL-urban + industrial exclusion) as its own layer, so the raw
// prob>=45 layer and the final mask can be toggled to see exactly what post-processing removed.
//
// The script has THREE scopes:
//   - AOI (Amansie West, ~20 km): SmallMinesDS overlay -- QA step 2c. Loads on run.
//   - NATIONAL (section 2a): un-clipped prob/mask layers (visibility OFF by default -- tick
//     them on in the Layers panel), a top-of-map dropdown to fly to the 2a checklist locations,
//     and the national mask area at 100 m (folds in QA step 2b).
//   - PERMUTATION PREVIEW (section 2d, added 2026-09-08): live cutoff-45-vs-70 and GHSL-vs-DW
//     urban-mask permutations + per-permutation national area, WITHOUT re-exporting build_03.

var ASSET_HOME = "projects/rgee-auth-tillam/assets/ghana_mining";
var AOI_CENTER = ee.Geometry.Point([-1.942743, 6.060442]);
var AOI_HALFWIDTH_M = 20500.000000;
var aoi = AOI_CENTER.buffer(AOI_HALFWIDTH_M * 1.4142).bounds();  // *sqrt(2) ~ circumscribes the R script's square AOI

// -- Sources --
var barenblitt = ee.FeatureCollection(ASSET_HOME + "/gt_compare_barenblitt_raw");
var maus  = ee.FeatureCollection(ASSET_HOME + "/gt_compare_maus_raw");
var tang  = ee.FeatureCollection(ASSET_HOME + "/gt_compare_tang_raw");
var smds  = ee.FeatureCollection(ASSET_HOME + "/gt_compare_smallminesds_aoi");
// Mosaic the 2022 c4 probability tiles (0-100 uint8). ghana_mining is a folder, not an
// ImageCollection, so enumerate it and keep the tiles whose id contains '/mine_prob_ghana_c4_2022_t'
// -- that substring also matches any lingering split sub-tiles (_t06s01 etc.), harmless for a
// mosaic (same values where they overlap the recombined parent). listAssets() runs client-side
// synchronously in the Code Editor.
var probIds = ee.data.listAssets(ASSET_HOME).assets
  .map(function (a) { return a.id || a.name; })
  .filter(function (n) { return n.indexOf("/mine_prob_ghana_c4_2022_t") > -1; });
print("2022 c4 prob tiles found (expect ~17):", probIds.length, probIds);

var prob = ee.ImageCollection(probIds.map(function (id) { return ee.Image(id); }))
  .mosaic()
  .clip(aoi);

// build_03's post-processed 2022 mask -- single national image (cutoff 45 -> GHSL-urban knockout
// -> Barenblitt industrial knockout, all applied at export time). 1 = mine, everything else masked.
var mask22 = ee.Image(ASSET_HOME + "/mine_mask_ghana_c4_2022").selfMask().clip(aoi);

// -- Live Sentinel-2 2022 composite (cloud-masked median, matches SmallMinesDS/classifier vintage) --
function maskS2(img) {
  var scl = img.select("SCL");
  return img.updateMask(scl.neq(3).and(scl.neq(9))).divide(10000);
}
var s2_2022 = ee.ImageCollection("COPERNICUS/S2_SR_HARMONIZED")
  .filterBounds(aoi)
  .filterDate("2022-01-01", "2022-12-31")
  .filter(ee.Filter.lt("CLOUDY_PIXEL_PERCENTAGE", 40))
  .map(maskS2)
  .median()
  .select(["B4", "B3", "B2"])
  .clip(aoi);

// -- Display --
Map.centerObject(aoi, 12);
Map.addLayer(s2_2022, {min: 0, max: 0.3}, "Sentinel-2 2022 (true colour)", true);
Map.addLayer(prob.gte(45).selfMask(), {palette: ["00c3ff"]}, "Classifier c4 raw prob >= 45% (2022)", true);
Map.addLayer(mask22, {palette: ["ff8c00"]}, "build_03 mask 2022 (post GHSL-urban + industrial)", true);
Map.addLayer(smds.style({color: "ff2a2a", fillColor: "00000000", width: 2}), {}, "SmallMinesDS (real outlines)", true);
Map.addLayer(barenblitt.style({color: "450457", fillColor: "00000000", width: 2}), {}, "Barenblitt 2019 (raw, both types)", true);
Map.addLayer(maus.style({color: "2171B5", fillColor: "00000000", width: 2}), {}, "Maus et al. 2022 (raw)", true);
Map.addLayer(tang.style({color: "D94701", fillColor: "00000000", width: 2}), {}, "Tang & Werner 2023 (raw)", true);

print("SmallMinesDS patches:", smds.size(), " Barenblitt polygons:", barenblitt.size(),
      " Maus polygons:", maus.size(), " Tang polygons:", tang.size());


// ============================================================================
// 2a -- NATIONAL VISUAL CHECKLIST
// Un-clipped versions of the same two layers, added with visibility = false so the AOI
// view above still loads first. Tick "NATIONAL ..." on in the Layers panel, then use the
// dropdown at the top of the map to fly to each checklist location. Google satellite is set
// as the basemap for context (there is no national S2 composite -- too heavy to compute live).
// ============================================================================
Map.setOptions("SATELLITE");

var probNat   = ee.ImageCollection(probIds.map(function (id) { return ee.Image(id); })).mosaic();
var mask22Nat = ee.Image(ASSET_HOME + "/mine_mask_ghana_c4_2022").selfMask();

Map.addLayer(probNat.gte(45).selfMask(), {palette: ["00c3ff"]}, "NATIONAL raw prob >= 45 (2022)", false);
Map.addLayer(probNat.gte(60).selfMask(), {palette: ["0060ff"]}, "NATIONAL raw prob >= 60 (2022)", false);
Map.addLayer(mask22Nat,                  {palette: ["ff8c00"]}, "NATIONAL build_03 mask (2022)",  false);

// QA step 2b -- national mine-mask area at 100 m. The mask is already masked to mine pixels,
// so sum(pixelArea) over its own bbox = total mine area. Expect low hundreds of km2; low
// thousands, or a large northern share, means something is wrong.
var areaKm2 = mask22Nat.multiply(ee.Image.pixelArea()).rename("m2").reduceRegion({
  reducer:   ee.Reducer.sum(),
  geometry:  mask22Nat.geometry(),
  scale:     100,
  maxPixels: 1e13,
  bestEffort: false
});
print("2022 NATIONAL mine-mask area, km2 (expect low hundreds):",
      ee.Number(areaKm2.get("m2")).divide(1e6));

// name -> [lon, lat, zoom]. "DARK:" = should have little/no mask; "industrial" = should be
// knocked out by the Barenblitt minetype==2 exclusion (SW coverage only).
var CHECK_SITES = {
  "belt - Obuasi":                 [-1.666, 6.202, 12],
  "belt - Dunkwa / Offin":         [-1.780, 5.972, 12],
  "belt - Tarkwa":                 [-1.995, 5.301, 12],
  "belt - Prestea":                [-2.143, 5.433, 12],
  "Eastern - Kibi / Atewa fringe": [-0.552, 6.163, 12],
  "Eastern - Anyinam":             [-0.545, 6.363, 13],
  "Ashanti - Amansie (AOI)":       [-1.943, 6.060, 12],
  "River - Pra corridor":          [-1.503, 5.720, 12],
  "River - Ankobra corridor":      [-2.230, 5.150, 12],
  "DARK: Kumasi metro":            [-1.616, 6.700, 12],
  "DARK: Accra / Tema":            [-0.100, 5.630, 11],
  "DARK: Sunyani":                 [-2.328, 7.339, 12],
  "DARK: Atewa forest core":      [-0.560, 6.230, 12],
  "DARK: Lake Volta":              [ 0.050, 6.900, 9],
  "DARK: Bui reservoir":           [-2.245, 8.280, 11],
  "industrial: Obuasi lease":      [-1.680, 6.150, 13],
  "industrial: Ahafo / Kenyasi":   [-2.360, 7.010, 12],
  "industrial: Tarkwa Gold":       [-1.995, 5.301, 13],
  "industrial: Damang":            [-1.820, 5.520, 13],
  "industrial: Chirano":           [-2.230, 6.230, 13],
  "industrial: Bibiani":           [-2.330, 6.460, 13],
  "industrial: Prestea / Bogoso":  [-2.143, 5.433, 13],
  "North: Wa (expect empty)":      [-2.500, 10.060, 10],
  "North: Tamale (expect empty)":  [-0.840, 9.400, 10]
};

Map.add(ui.Select({
  items: Object.keys(CHECK_SITES),
  placeholder: "2a checklist - jump to location...",
  onChange: function (key) {
    var s = CHECK_SITES[key];
    Map.setCenter(s[0], s[1], s[2]);
  },
  style: {position: "top-center"}
}));


// ============================================================================
// 2d -- CUTOFF / MASK PERMUTATION PREVIEW  (added 2026-09-08)
// Live preview of what build_03's output WOULD look like under a higher probability cutoff and
// under the GHSL-urban vs Dynamic-World-built masks -- WITHOUT re-exporting build_03. All layers
// national + un-clipped, visibility OFF (tick on in the Layers panel), use the dropdown to fly.
// Console prints the national 100 m area for each permutation.
//
// Decide from this: (a) cutoff 45 vs 70, (b) GHSL>2000 vs DW built as the urban knockout, (c)
// whether the two masks are redundant or complementary. Then set CUTOFF / add the DW mask in
// build_03_embedding_panel.R and re-export once.
// ============================================================================
var CUTOFF_HI   = 70;      // the candidate higher cutoff
var GHSL_THRESH = 2000;    // build_03's current urban knockout (of 10000 ~= 20% built)
var DW_THRESH   = 0.20;    // Dynamic World annual mean P(built)
var GHANA = ee.FeatureCollection(ASSET_HOME + "/rs05_ghana").geometry();

var ghslBuilt = ee.ImageCollection("JRC/GHSL/P2023A/GHS_BUILT_S")
  .filterDate("2020-01-01", "2021-01-01").first().select("built_surface");   // 2020 epoch ~ 2022
var ghslUrban = ghslBuilt.gt(GHSL_THRESH);                                   // 1 = urban, knock OUT

var dwBuilt = ee.ImageCollection("GOOGLE/DYNAMICWORLD/V1")
  .filterDate("2022-01-01", "2023-01-01").select("built").mean();            // mean P(built) 2022
var dwUrban = dwBuilt.gt(DW_THRESH);                                         // 1 = built, knock OUT

var p45  = probNat.gte(45).selfMask();
var p70  = probNat.gte(CUTOFF_HI).selfMask();
var p70g = probNat.gte(CUTOFF_HI).and(ghslUrban.not()).selfMask();          // cutoff70 + GHSL mask
var p70d = probNat.gte(CUTOFF_HI).and(dwUrban.not()).selfMask();            // cutoff70 + DW mask
var p70gd = probNat.gte(CUTOFF_HI)
  .and(ghslUrban.not()).and(dwUrban.not()).selfMask();                      // cutoff70 + BOTH (candidate)

// what each step removes, so you can see it directly
var dropCut  = probNat.gte(45).and(probNat.lt(CUTOFF_HI)).selfMask();       // lost to 45 -> 70
var dropDw   = probNat.gte(CUTOFF_HI).and(dwUrban).selfMask();              // lost to the DW mask (from cutoff70)
var dropGhsl = probNat.gte(CUTOFF_HI).and(ghslUrban).selfMask();           // lost to the GHSL mask (from cutoff70)

Map.addLayer(dwBuilt,   {min: 0, max: 1, palette: ["000000", "ffffff"]}, "ref DW mean P(built) 2022", false);
Map.addLayer(ghslUrban.selfMask(), {palette: ["888888"]}, "ref GHSL built > " + GHSL_THRESH, false);

Map.addLayer(p45,   {palette: ["00c3ff"]}, "PREVIEW prob >= 45 (baseline)", false);
Map.addLayer(p70,   {palette: ["00ffd0"]}, "PREVIEW prob >= " + CUTOFF_HI + " (no mask)", false);
Map.addLayer(p70g,  {palette: ["ff8c00"]}, "PREVIEW cutoff" + CUTOFF_HI + " + GHSL mask", false);
Map.addLayer(p70d,  {palette: ["ffe100"]}, "PREVIEW cutoff" + CUTOFF_HI + " + DW mask", false);
Map.addLayer(p70gd, {palette: ["ff2a2a"]}, "PREVIEW cutoff" + CUTOFF_HI + " + GHSL + DW (candidate)", false);

Map.addLayer(dropCut,  {palette: ["555555"]}, "removed by 45 -> " + CUTOFF_HI + " bump", false);
Map.addLayer(dropGhsl, {palette: ["c000c0"]}, "removed by GHSL mask (from cutoff" + CUTOFF_HI + ")", false);
Map.addLayer(dropDw,   {palette: ["ff00ff"]}, "removed by DW mask (from cutoff" + CUTOFF_HI + ")", false);

function areaKm2Nat(binImg, label) {
  var a = binImg.gt(0).multiply(ee.Image.pixelArea()).reduceRegion({
    reducer: ee.Reducer.sum(), geometry: GHANA, scale: 100, maxPixels: 1e13,
    bestEffort: false, tileScale: 8
  });
  print(label + " -- national km2 @100m:", ee.Number(a.values().get(0)).divide(1e6));
}
areaKm2Nat(p45,   "prob >= 45");
areaKm2Nat(p70,   "prob >= " + CUTOFF_HI);
areaKm2Nat(p70g,  "cutoff" + CUTOFF_HI + " + GHSL");
areaKm2Nat(p70d,  "cutoff" + CUTOFF_HI + " + DW");
areaKm2Nat(p70gd, "cutoff" + CUTOFF_HI + " + GHSL + DW (candidate)");


// --- DW threshold sweep: does a STRICTER DW stop eating real pits while still taking settlement? ---
// Candidate = cutoff CUTOFF_HI + GHSL(always on) + DW at the given threshold. "removedByDW@x" shows
// what DW adds on top of GHSL, so you can see exactly what each threshold clips.
[0.35, 0.50].forEach(function (t) {
  var dwT     = dwBuilt.gt(t);
  var keepGD  = probNat.gte(CUTOFF_HI).and(ghslUrban.not()).and(dwT.not()).selfMask();
  var removed = probNat.gte(CUTOFF_HI).and(ghslUrban.not()).and(dwT).selfMask();
  Map.addLayer(keepGD,  {palette: ["ff2a2a"]}, "PREVIEW cutoff" + CUTOFF_HI + " + GHSL + DW@" + t, false);
  Map.addLayer(removed, {palette: ["ff00ff"]}, "removed by DW@" + t + " (on top of GHSL, from cutoff" + CUTOFF_HI + ")", false);
  areaKm2Nat(keepGD, "cutoff" + CUTOFF_HI + " + GHSL + DW@" + t);
});

// --- GHSL 1000 vs 2000: could just lowering the GHSL threshold do DW@0.35's job, no DW dependency? ---
// "removed by GHSL 1000-2000 ring" = extra area a 2000->1000 threshold clips; compare it visually to
// "removed by DW@0.35" -- same ground (redundant) or different (DW catches built-up GHSL never sees)?
var ghslUrban1000 = ghslBuilt.gt(1000);
var ghslRing      = ghslBuilt.gt(1000).and(ghslBuilt.lte(2000));
var p70g1000      = probNat.gte(CUTOFF_HI).and(ghslUrban1000.not()).selfMask();
var dropGhslRing  = probNat.gte(CUTOFF_HI).and(ghslRing).selfMask();
Map.addLayer(p70g1000,     {palette: ["ff8c00"]}, "PREVIEW cutoff" + CUTOFF_HI + " + GHSL@1000", false);
Map.addLayer(dropGhslRing, {palette: ["c000c0"]}, "removed by GHSL 1000-2000 ring (from cutoff" + CUTOFF_HI + ")", false);
areaKm2Nat(p70g1000, "cutoff" + CUTOFF_HI + " + GHSL@1000");

